def _check_weights_parameters(self):
    """Check the parameter of the Dirichlet distribution."""
    if self.weight_concentration_prior is None:
        self.weight_concentration_prior_ = 1.0 / self.n_components
    elif self.weight_concentration_prior > 0.0:
        self.weight_concentration_prior_ = self.weight_concentration_prior
    else:
        raise ValueError("The parameter 'weight_concentration_prior' should be greater than 0., but got %.3f." % self.weight_concentration_prior)

def _check_means_parameters(self, X):
    """Check the parameters of the Gaussian distribution.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
        """
    _, n_features = X.shape
    if self.mean_precision_prior is None:
        self.mean_precision_prior_ = 1.0
    elif self.mean_precision_prior > 0.0:
        self.mean_precision_prior_ = self.mean_precision_prior
    else:
        raise ValueError("The parameter 'mean_precision_prior' should be greater than 0., but got %.3f." % self.mean_precision_prior)
    if self.mean_prior is None:
        self.mean_prior_ = X.mean(axis=0)
    else:
        self.mean_prior_ = check_array(self.mean_prior, dtype=[np.float64, np.float32], ensure_2d=False)
        _check_shape(self.mean_prior_, (n_features,), 'means')

def _check_precision_parameters(self, X):
    """Check the prior parameters of the precision distribution.

        Parameters
        ----------
        X : array-like of shape (n_samples, n_features)
        """
    _, n_features = X.shape
    if self.degrees_of_freedom_prior is None:
        self.degrees_of_freedom_prior_ = n_features
    elif self.degrees_of_freedom_prior > n_features - 1.0:
        self.degrees_of_freedom_prior_ = self.degrees_of_freedom_prior
    else:
        raise ValueError("The parameter 'degrees_of_freedom_prior' should be greater than %d, but got %.3f." % (n_features - 1, self.degrees_of_freedom_prior))

def _estimate_weights(self, nk):
    """Estimate the parameters of the Dirichlet distribution.

        Parameters
        ----------
        nk : array-like of shape (n_components,)
        """
    if self.weight_concentration_prior_type == 'dirichlet_process':
        self.weight_concentration_ = (1.0 + nk, self.weight_concentration_prior_ + np.hstack((np.cumsum(nk[::-1])[-2::-1], 0)))
    else:
        self.weight_concentration_ = self.weight_concentration_prior_ + nk

def _estimate_log_weights(self):
    if self.weight_concentration_prior_type == 'dirichlet_process':
        digamma_sum = digamma(self.weight_concentration_[0] + self.weight_concentration_[1])
        digamma_a = digamma(self.weight_concentration_[0])
        digamma_b = digamma(self.weight_concentration_[1])
        return digamma_a - digamma_sum + np.hstack((0, np.cumsum(digamma_b - digamma_sum)[:-1]))
    else:
        return digamma(self.weight_concentration_) - digamma(np.sum(self.weight_concentration_))

def _estimate_log_prob(self, X):
    _, n_features = X.shape
    log_gauss = _estimate_log_gaussian_prob(X, self.means_, self.precisions_cholesky_, self.covariance_type) - 0.5 * n_features * np.log(self.degrees_of_freedom_)
    log_lambda = n_features * np.log(2.0) + np.sum(digamma(0.5 * (self.degrees_of_freedom_ - np.arange(0, n_features)[:, np.newaxis])), 0)
    return log_gauss + 0.5 * (log_lambda - n_features / self.mean_precision_)

def _set_parameters(self, params):
    self.weight_concentration_, self.mean_precision_, self.means_, self.degrees_of_freedom_, self.covariances_, self.precisions_cholesky_ = params
    if self.weight_concentration_prior_type == 'dirichlet_process':
        weight_dirichlet_sum = self.weight_concentration_[0] + self.weight_concentration_[1]
        tmp = self.weight_concentration_[1] / weight_dirichlet_sum
        self.weights_ = self.weight_concentration_[0] / weight_dirichlet_sum * np.hstack((1, np.cumprod(tmp[:-1])))
        self.weights_ /= np.sum(self.weights_)
    else:
        self.weights_ = self.weight_concentration_ / np.sum(self.weight_concentration_)
    if self.covariance_type == 'full':
        self.precisions_ = np.array([np.dot(prec_chol, prec_chol.T) for prec_chol in self.precisions_cholesky_])
    elif self.covariance_type == 'tied':
        self.precisions_ = np.dot(self.precisions_cholesky_, self.precisions_cholesky_.T)
    else:
        self.precisions_ = self.precisions_cholesky_ ** 2
